/**
 * East Asian font DOCX round-trip (change ooxml-roundtrip-fidelity, Font family fix).
 *
 * - All four `w:rFonts` slots (ascii/hAnsi/eastAsia/cs) survive
 *   load → save → reload alongside theme refs.
 * - CJK runs (等线/DengXian, 宋体/SimSun) keep their eastAsia font instead of
 *   collapsing to Arial/Calibri.
 *
 * Fixture is generated by `bun run e2e/fixtures/generate-fixtures.ts`
 * (generateEastAsianFontRoundtripDocx).
 *
 * Word真机核验步骤见 e2e/fixtures/east-asian-font-roundtrip-word-check.md.
 */

import { test, expect, type Page } from '@playwright/test';
import { EditorPage } from '../helpers/editor-page';
import * as assertions from '../helpers/assertions';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import JSZip from 'jszip';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const FONT_DOCX = path.join(__dirname, '..', 'fixtures', 'east-asian-font-roundtrip.docx');

async function saveDownload(page: Page): Promise<string> {
  const downloadPromise = page.waitForEvent('download');
  await page.locator('text=Save').click();
  const download = await downloadPromise;
  const downloadPath = await download.path();
  expect(downloadPath).toBeTruthy();
  return downloadPath!;
}

test.describe('East Asian font round-trip', () => {
  let editor: EditorPage;

  test.beforeEach(async ({ page }) => {
    editor = new EditorPage(page);
    await editor.goto();
    await editor.waitForReady();
  });

  test('eastAsia/cs slots survive save → reload (DengXian, SimSun)', async ({ page }) => {
    await editor.loadDocxFile(FONT_DOCX);

    await assertions.assertDocumentContainsText(page, 'DengXian CJK text.');
    await assertions.assertDocumentContainsText(page, 'SimSun body text.');

    const downloadPath = await saveDownload(page);
    const zip = await JSZip.loadAsync(fs.readFileSync(downloadPath));
    const docXml = await zip.file('word/document.xml')!.async('text');

    // All four slots are written back verbatim — eastAsia is the CJK font,
    // not a collapsed Arial/Calibri.
    expect(docXml).toContain('w:eastAsia="等线"');
    expect(docXml).toContain('w:eastAsia="宋体"');
    expect(docXml).toContain('w:ascii="Calibri"');
    expect(docXml).toContain('w:ascii="Times New Roman"');
    expect(docXml).toContain('w:cs="Calibri"');
    expect(docXml).toContain('w:cs="Times New Roman"');
    // Third paragraph keeps its theme color alongside the CJK font.
    expect(docXml).toContain('w:themeColor="accent1"');
    // Schema spelling for the CS theme ref (Word ignores w:csTheme).
    expect(docXml).not.toMatch(/w:csTheme=/);

    const tempPath = path.join(__dirname, '..', 'fixtures', '_temp-east-asian-font.docx');
    fs.writeFileSync(tempPath, fs.readFileSync(downloadPath));
    try {
      await editor.loadDocxFile(tempPath);
      await assertions.assertDocumentContainsText(page, 'DengXian CJK text.');
      await assertions.assertDocumentContainsText(page, 'SimSun body text.');
    } finally {
      if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    }
  });
});
